local ParadeShieldMaker = {}
local PRODUCTS = {
    simple_wood_parade_shield = { name = "Preprost leseni paradni ščit", woodCost = 3, paintCost = 1, time = 4, cost = 80, prestige = 5, happiness = 2, description = "Preprost leseni paradni ščit za parade." },
    iron_banded_parade_shield = { name = "Železnopasni paradni ščit", woodCost = 3, ironCost = 1, paintCost = 1, time = 7, cost = 220, prestige = 12, happiness = 3, description = "Železnopasni paradni ščit za trgovce." },
    silver_trimmed_parade_shield = { name = "Srebrnoobrobljeni paradni ščit", woodCost = 3, silverCost = 1, ironCost = 1, paintCost = 1, time = 10, cost = 540, prestige = 22, happiness = 4, description = "Srebrnoobrobljeni paradni ščit za plemiče." },
    gold_trimmed_parade_shield = { name = "Zlatookrasni paradni ščit", woodCost = 3, goldCost = 1, silverCost = 1, ironCost = 1, paintCost = 1, time = 14, cost = 1200, prestige = 35, happiness = 6, description = "Zlatookrasni paradni ščit za visoke plemiče." },
    jewel_set_parade_shield = { name = "Draguljasta paradni ščit", woodCost = 3, goldCost = 1, silverCost = 1, ironCost = 1, paintCost = 1, jewelCost = 1, time = 18, cost = 2600, prestige = 50, happiness = 8, description = "Paradni ščit z draguljem za visoko plemstvo." },
    royal_grand_parade_shield = { name = "Kraljevski veliki paradni ščit", woodCost = 5, goldCost = 3, silverCost = 2, ironCost = 1, paintCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 5800, prestige = 72, happiness = 13, description = "Veliki kraljevski paradni ščit z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    parade_shield_workshop = { name = "Paradna ščitna delavnica", cost = { gold = 280, wood = 140, stone = 120, iron = 4, paint = 6 }, upkeep = 6, qualityBonus = 5 },
    armory_loft = { name = "Orožarna podstrešje", cost = { gold = 1000, wood = 280, stone = 240, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_shield_atelier = { name = "Mojstrski ščitni atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_armory_palace = { name = "Kraljevska orožarna palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
ParadeShieldMaker.woodStock = 18; ParadeShieldMaker.ironStock = 10; ParadeShieldMaker.paintStock = 12; ParadeShieldMaker.silverStock = 6; ParadeShieldMaker.goldStock = 6; ParadeShieldMaker.jewelStock = 4; ParadeShieldMaker.pearlStock = 4
ParadeShieldMaker.productStock = {}; ParadeShieldMaker.buildings = {}; ParadeShieldMaker.maker = nil; ParadeShieldMaker.activeMaking = {}; ParadeShieldMaker.totalProducts = 0; ParadeShieldMaker.dayTimer = 0
function ParadeShieldMaker.init() ParadeShieldMaker.woodStock=18; ParadeShieldMaker.ironStock=10; ParadeShieldMaker.paintStock=12; ParadeShieldMaker.silverStock=6; ParadeShieldMaker.goldStock=6; ParadeShieldMaker.jewelStock=4; ParadeShieldMaker.pearlStock=4; ParadeShieldMaker.productStock={}; ParadeShieldMaker.buildings={}; ParadeShieldMaker.maker=nil; ParadeShieldMaker.activeMaking={}; ParadeShieldMaker.totalProducts=0; ParadeShieldMaker.dayTimer=0; print("[ParadeShieldMaker] Royal Parade Shield Maker System initialized (6 products, 4 buildings)") end
function ParadeShieldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ParadeShieldMaker.maker={name=n or ("Paradni ščitar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Paradni ščitar najet: %s (spretnost: %d)",ParadeShieldMaker.maker.name,s),"success") end; return true end
function ParadeShieldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ParadeShieldMaker.build(id) local ok,e=ParadeShieldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ParadeShieldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ParadeShieldMaker.getQualityBonus() local b=0; for _,bd in ipairs(ParadeShieldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ParadeShieldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ParadeShieldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and ParadeShieldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.paintCost and ParadeShieldMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and ParadeShieldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ParadeShieldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ParadeShieldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ParadeShieldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ParadeShieldMaker.buildings==0 then return false,"Potrebna paradna ščitna delavnica" end; if not ParadeShieldMaker.maker then return false,"Potreben paradni ščitar" end; return true end
function ParadeShieldMaker.make(pt,qty) qty=qty or 1; local ok,e=ParadeShieldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ParadeShieldMaker.woodStock=ParadeShieldMaker.woodStock-d.woodCost*qty end; if d.ironCost then ParadeShieldMaker.ironStock=ParadeShieldMaker.ironStock-d.ironCost*qty end; if d.paintCost then ParadeShieldMaker.paintStock=ParadeShieldMaker.paintStock-d.paintCost*qty end; if d.silverCost then ParadeShieldMaker.silverStock=ParadeShieldMaker.silverStock-d.silverCost*qty end; if d.goldCost then ParadeShieldMaker.goldStock=ParadeShieldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ParadeShieldMaker.jewelStock=ParadeShieldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ParadeShieldMaker.pearlStock=ParadeShieldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ParadeShieldMaker.maker then t=math.max(1,t-math.floor(ParadeShieldMaker.maker.skill/13)) end; table.insert(ParadeShieldMaker.activeMaking,{id="paradeshield_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ParadeShieldMaker.completeMaking(m) local q=1.0+(ParadeShieldMaker.getQualityBonus()/100); if ParadeShieldMaker.maker then q=q+(ParadeShieldMaker.maker.skill/140) end; q=math.min(2.5,q); ParadeShieldMaker.productStock[m.productType]=(ParadeShieldMaker.productStock[m.productType] or 0)+m.quantity; ParadeShieldMaker.totalProducts=ParadeShieldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ParadeShieldMaker.maker then ParadeShieldMaker.maker.itemsMade=ParadeShieldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ParadeShieldMaker.maker.skill=math.min(100,ParadeShieldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Paradni ščit izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"paradeshield.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ParadeShieldMaker.update(dt) if not _G.state then return end; ParadeShieldMaker.dayTimer=ParadeShieldMaker.dayTimer+dt; if ParadeShieldMaker.dayTimer>=30 then ParadeShieldMaker.dayTimer=0; for i=#ParadeShieldMaker.activeMaking,1,-1 do local m=ParadeShieldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ParadeShieldMaker.completeMaking(m); table.remove(ParadeShieldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ParadeShieldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ParadeShieldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ParadeShieldMaker.getStats() return {woodStock=ParadeShieldMaker.woodStock,ironStock=ParadeShieldMaker.ironStock,paintStock=ParadeShieldMaker.paintStock,silverStock=ParadeShieldMaker.silverStock,goldStock=ParadeShieldMaker.goldStock,jewelStock=ParadeShieldMaker.jewelStock,pearlStock=ParadeShieldMaker.pearlStock,productStock=ParadeShieldMaker.productStock,numBuildings=#ParadeShieldMaker.buildings,hasMaker=ParadeShieldMaker.maker~=nil,makerName=ParadeShieldMaker.maker and ParadeShieldMaker.maker.name or "—",makerSkill=ParadeShieldMaker.maker and ParadeShieldMaker.maker.skill or 0,activeMaking=#ParadeShieldMaker.activeMaking,totalProducts=ParadeShieldMaker.totalProducts} end
return ParadeShieldMaker
